(function(){
'use strict';
const posts=window.HlebArticleData;
const meta={title:'Статьи о расстойке теста и хлебопечении — HLEB-FORMA',h1:'Для тех, кто печёт хлеб',desc:'Практические советы о выборе корзинок, натуральном ротанге, расстойке теста и уходе за формами.'};
const categories=[['all','Все статьи'],['choice','Выбор корзинок'],['care','Уход'],['baking','Хлебопечение'],['material','Материалы']];
const forms=[['all','Любая форма'],['round','Круглая'],['oval','Овальная'],['baguette','Багетная'],['triangle','Треугольная'],['heart','Сердце'],['diamond','Ромб'],['boat','Лодочка']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href=p=>'../blog/'+p.alias+'/';
const fmt=n=>Number(n).toLocaleString('ru-RU')+' ₽';
const category=p=>categories.find(c=>c[0]===p.category)?.[1]||'Статья';
const get=alias=>posts.find(p=>p.alias===alias);
const title=p=>p.title+' — HLEB-FORMA';
function capacity(p){const ns=String(p.weightText).match(/\d+/g)?.map(Number)||[];return ns.length>=2?[Math.min(ns[0],ns[1]),Math.max(ns[0],ns[1])]:[p.weight,p.weight];}
function recommend(products,weight,shape='all'){
 const w=Number(weight);if(!Number.isFinite(w)||w<1||w>100000)return {exact:false,items:[]};
 const candidates=products.filter(p=>Number(p.weight)>0&&!['tool','cloth'].includes(p.shape)&&(shape==='all'||p.shape===shape));
 const distance=p=>{const [a,b]=capacity(p);return Math.max(a-w,w-b,0);};
 const ranked=candidates.slice().sort((a,b)=>distance(a)-distance(b)||Number(b.exact)-Number(a.exact)||a.price-b.price);
 const exact=ranked.filter(p=>distance(p)===0);return {exact:exact.length>0,items:(exact.length?exact:ranked).slice(0,3)};
}
function product(p){const link='index.html#product-'+esc(p.id);return '<article class="ar-product"><a href="'+link+'">'+(p.image?'<img src="'+esc(p.image)+'" alt="'+esc(p.exact===false?'Фото аналогичной модели':p.title)+'" loading="lazy">':'')+'<span class="ar-kicker">'+esc(p.sku)+'</span><strong>'+esc(p.title)+'</strong></a><p>'+esc(p.weight?p.weightText+' теста':p.weightText)+'</p>'+(p.exact===false?'<small>Фото аналога</small>':'')+'<div class="ar-price">'+(p.oldPrice>p.price?'<del>'+fmt(p.oldPrice)+'</del>':'')+'<b>'+fmt(p.price)+'</b></div><a class="btn btn-outline" href="'+link+'">Подробнее ↗</a></article>';}
function tile(p){return '<article class="ar-tile" data-article-category="'+esc(p.category)+'"><a href="'+href(p)+'"><div class="ar-thumb"><img src="'+esc(p.image)+'" alt="'+esc(p.imageAlt||'')+'" loading="lazy" decoding="async"></div><div class="ar-tile-copy"><span class="ar-kicker">'+esc(category(p))+'</span><h2>'+esc(p.title)+'</h2><p>'+esc(p.desc)+'</p><span class="ar-read">Читать статью ↗</span></div></a></article>';}
function listing(){const p=posts[0];return '<div class="ar-shop ar-journal"><header class="ar-journal-hero"><img class="ar-journal-photo" src="'+esc(p.image)+'" alt="" fetchpriority="high" decoding="async"><div class="container ar-journal-inner"><nav class="breadcrumb" aria-label="Хлебные крошки"><a href="v3/index.html">Главная</a> / Статьи</nav><h1>'+esc(meta.h1)+'</h1></div></header><div class="container ar-journal-main"><a class="ar-journal-feature" href="'+href(p)+'" data-ar-feature><div><h2>'+esc(p.title)+'</h2><p>'+esc(p.desc)+'</p></div><span class="ar-read">Читать статью ↗</span></a><section class="ar-list" aria-label="Все статьи"><div class="ar-filters" role="group" aria-label="Темы статей">'+categories.map(([k,v])=>'<button type="button" data-ar-filter="'+k+'" aria-pressed="'+(k==='all')+'">'+esc(v)+'</button>').join('')+'</div><p class="ar-count ar-visually-hidden" data-ar-count role="status">'+posts.length+' материалов</p><div class="ar-grid">'+posts.slice(1).map(tile).join('')+'</div></section><div class="ar-end"><div><h2>От знаний к выпечке</h2><p>Найдите форму под свой рецепт в каталоге.</p></div><a class="btn btn-primary" href="../katalog/">Весь каталог ↗</a></div></div></div>';}
function result(r){return '<p class="ar-match">'+(r.items.length?(r.exact?'Модели с указанной вместимостью, соответствующей вашему весу.':'Точного совпадения нет. Ближайшие модели — сравните вместимость и уточните выбор.'):'Нет моделей с известной вместимостью для выбранной формы или указан неверный вес.')+'</p><div class="ar-products">'+r.items.map(product).join('')+'</div>';}
function finder(products){return '<section class="ar-finder" id="article-finder"><span class="ar-kicker">Интерактивный подбор</span><h2>Найдите корзинку под ваш рецепт</h2><p>Укажите вес тестовой заготовки до выпечки и желаемую форму.</p><div class="ar-finder-fields"><label>Вес теста, г<input type="number" min="1" max="100000" step="1" inputmode="numeric" value="700" data-ar-weight></label><label>Форма хлеба<select data-ar-shape>'+forms.map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label></div><div data-ar-recommend aria-live="polite">'+result(recommend(products,700))+'</div><a class="ar-read" href="../katalog/">Посмотреть весь ассортимент ↗</a></section>';}
function table(products){return '<details class="ar-table" open><summary>Таблица размеров и вместимости</summary><div class="ar-table-scroll"><table><thead><tr><th>Модель</th><th>Форма</th><th>Вес теста</th><th>Размер</th><th>Цена</th></tr></thead><tbody>'+products.filter(p=>!['tool','cloth'].includes(p.shape)).slice().sort((a,b)=>(a.weight||Infinity)-(b.weight||Infinity)).map(p=>'<tr><td><a href="index.html#product-'+esc(p.id)+'">'+esc(p.sku)+'</a></td><td>'+esc(forms.find(f=>f[0]===p.shape)?.[1]||p.kind)+'</td><td>'+esc(p.weightText)+'</td><td>'+esc(p.size)+'</td><td>'+fmt(p.price)+'</td></tr>').join('')+'</tbody></table></div><p>Вместимость — ориентир по данным каталога. Фактический объём зависит от рецепта.</p></details>';}
function sidebar(p,products){
 const items=p.related.map(id=>products.find(x=>x.id===id)).filter(Boolean);
 const facts=(p.facts||[]).map(f=>'<li>'+esc(f)+'</li>').join('');
 const slider=items.length?'<section class="ar-sidebar-promo" aria-labelledby="ar-promo-title"><h2 id="ar-promo-title">Из каталога</h2><div class="ar-slider" data-ar-slider aria-label="Подборка корзинок" aria-roledescription="карусель"><div class="ar-slides">'+items.map((item,i)=>'<div class="ar-slide" data-ar-slide data-active="'+(i===0)+'"'+(i===0?'':' aria-hidden="true" inert')+'>'+product(item)+'</div>').join('')+'</div>'+(items.length>1?'<div class="ar-slider-controls" data-ar-controls hidden><button type="button" data-ar-step="-1" aria-label="Предыдущий товар">‹</button><span class="ar-slider-count" data-ar-position>1 / '+items.length+'</span><button type="button" data-ar-toggle aria-label="Приостановить смену товаров">Ⅱ</button><button type="button" data-ar-step="1" aria-label="Следующий товар">›</button></div>':'')+'<span class="ar-sr-only" data-ar-slider-status role="status"></span></div></section>':'';
 return '<aside class="ar-right-rail" aria-label="Полезные сведения и товары">'+(facts?'<section class="ar-facts"><h2>Что важно знать</h2><ul>'+facts+'</ul></section>':'')+slider+'</aside>';
}
function articleFooter(){
 const icons={eye:'<path d="M2 12s3.6-6 10-6 10 6 10 6-3.6 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>',heart:'<path d="M20.8 8.6c0 4.2-8.8 9.7-8.8 9.7S3.2 12.8 3.2 8.6a4.7 4.7 0 0 1 8.8-2.3 4.7 4.7 0 0 1 8.8 2.3Z"/>',share:'<path d="M12 15V3m-4 4 4-4 4 4M5 11v8a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-8"/>'};
 const icon=k=>'<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[k]+'</svg>';
 return '<footer class="ar-author-footer" data-ar-engagement aria-label="Автор и действия со статьёй"><div class="ar-author"><span class="ar-author-avatar" aria-hidden="true">ЕВ</span><div><span class="ar-author-label">Автор статьи</span><strong>Евгений Вичканов</strong></div></div><div class="ar-article-actions"><span class="ar-views" title="Просмотры в этом браузере">'+icon('eye')+'<span data-ar-views>0</span><span class="ar-sr-only"> просмотров</span></span><button type="button" class="ar-like" data-ar-like aria-pressed="false" aria-label="Нравится" disabled>'+icon('heart')+'<span data-ar-like-count>0</span></button><button type="button" class="ar-share" data-ar-share disabled>'+icon('share')+'<span>Поделиться</span></button></div><small class="ar-engagement-note">Просмотры и лайки — в этом браузере (демо).</small><div class="ar-share-fallback" data-ar-share-fallback hidden><label>Ссылка на статью<input type="url" data-ar-share-url readonly></label></div><span class="ar-share-status" data-ar-share-status role="status"></span></footer>';
}
function normalizeEngagement(value){return {views:Number.isSafeInteger(value?.views)&&value.views>=0?value.views:0,liked:value?.liked===true};}
function article(p,products){
 const guide=p===posts[0];
 const content=p.sections.map(([h,b],i)=>'<section id="ar-section-'+i+'"'+(i===0?' class="ar-intro"':'')+'><h2>'+esc(h)+'</h2><p>'+esc(b)+'</p></section>');
 const related=posts.filter(x=>x!==p).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,3);
 const toc='<aside class="ar-aside" aria-labelledby="ar-toc-title"><h2 id="ar-toc-title">В этой статье</h2>'+p.sections.map(([h],i)=>'<a href="#ar-section-'+i+'" data-scroll="ar-section-'+i+'">'+esc(h)+'</a>'+(guide&&i===0?'<a href="#article-finder" data-scroll="article-finder">Подбор корзинки</a>':'')).join('')+'</aside>';
 return '<div class="ar-shop ar-detail"><header class="ar-journal-hero ar-detail-hero"><img class="ar-journal-photo" src="'+esc(p.image)+'" alt="'+esc(p.imageAlt||'')+'" fetchpriority="high" decoding="async"><div class="container ar-journal-inner"><nav class="breadcrumb" aria-label="Хлебные крошки"><a href="v3/index.html">Главная</a> / <a href="../blog/">Статьи</a> / '+esc(category(p))+'</nav><h1>'+esc(p.title)+'</h1></div></header><div class="container ar-detail-main"><div class="ar-body-grid">'+toc+'<article class="ar-content"><p class="ar-article-lead">'+esc(p.desc)+'</p>'+content[0]+(guide?finder(products):'')+content.slice(1).join('')+(guide?table(products):'')+(p.legacy?'<p class="ar-source">Редакция материала из <a href="https://hleb-forma.ru/blog/'+esc(p.alias)+'">архива Hleb-Forma</a>.</p>':'')+articleFooter()+'</article>'+sidebar(p,products)+'</div><section class="ar-related ar-related-posts" aria-labelledby="ar-related-title"><header class="ar-related-head"><h2 id="ar-related-title">Читайте также</h2><a class="ar-read" href="../blog/">Все статьи ↗</a></header><div class="ar-grid">'+related.map(tile).join('')+'</div></section></div></div>';
}
function create({products,app,page='listing'}){const render=()=>get(page)?article(get(page),products):listing();function update(){const root=app.querySelector('.ar-shop');if(!root)return;const w=root.querySelector('[data-ar-weight]'),s=root.querySelector('[data-ar-shape]'),out=root.querySelector('[data-ar-recommend]');if(w&&s&&out)out.innerHTML=result(recommend(products,w.value,s.value));}
app.addEventListener('input',e=>{if(e.target.matches?.('[data-ar-weight]'))update();});
app.addEventListener('change',e=>{if(e.target.matches?.('[data-ar-shape]'))update();});
app.addEventListener('click',e=>{const b=e.target.closest?.('[data-ar-filter]');if(!b)return;const root=b.closest('.ar-shop'),key=b.dataset.arFilter;root.querySelectorAll('[data-ar-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;const feature=root.querySelector('[data-ar-feature]');if(feature){feature.hidden=!['all','choice'].includes(key);if(!feature.hidden)n++;}root.querySelectorAll('[data-article-category]').forEach(x=>{x.hidden=key!=='all'&&x.dataset.articleCategory!==key;if(!x.hidden)n++;});root.querySelector('[data-ar-count]').textContent='Материалов: '+n;});
let engagement=null,viewed=false,stats={views:0,liked:false};
const post=get(page),engagementKey='hlebforma:article:'+page+':engagement';
function loadStats(){try{const raw=window.localStorage.getItem(engagementKey);if(raw!==null)stats=normalizeEngagement(JSON.parse(raw));}catch{}}
function saveStats(){try{window.localStorage.setItem(engagementKey,JSON.stringify(stats));}catch{}}
function syncEngagement(){if(!engagement)return;engagement.querySelector('[data-ar-views]').textContent=stats.views.toLocaleString('ru-RU');engagement.querySelector('[data-ar-like-count]').textContent=stats.liked?'1':'0';engagement.querySelector('[data-ar-like]').setAttribute('aria-pressed',String(stats.liked));}
function mountEngagement(){engagement=app.querySelector('[data-ar-engagement]');if(!engagement||!post)return;loadStats();if(!viewed){stats.views=Math.min(Number.MAX_SAFE_INTEGER,stats.views+1);viewed=true;saveStats();}syncEngagement();engagement.querySelector('[data-ar-like]').disabled=false;engagement.querySelector('[data-ar-share]').disabled=false;}
async function shareArticle(){const host=engagement;if(!host||!post)return;const url='https://web86.github.io/new_hlebforma/blog/'+encodeURIComponent(post.alias)+'/';const status=host.querySelector('[data-ar-share-status]'),fallback=host.querySelector('[data-ar-share-fallback]');status.textContent='';fallback.hidden=true;
 try{if(typeof window.navigator.share==='function'){await window.navigator.share({title:post.title,url});return;}}catch(error){if(error?.name==='AbortError')return;}
 try{if(window.navigator.clipboard?.writeText){await window.navigator.clipboard.writeText(url);status.textContent='Ссылка скопирована';return;}}catch{}
 fallback.hidden=false;const input=fallback.querySelector('[data-ar-share-url]');input.value=url;input.focus();input.select();status.textContent='Скопируйте ссылку вручную.';
}
app.addEventListener('click',e=>{const button=e.target.closest?.('[data-ar-like],[data-ar-share]');if(!button||!engagement||!engagement.contains(button))return;if(button.hasAttribute('data-ar-like')){loadStats();stats.liked=!stats.liked;saveStats();syncEngagement();}else return shareArticle();});
let timer=null,slider=null,slides=[],active=0,playing=true;
function unmount(){engagement=null;if(timer!==null)window.clearInterval(timer);timer=null;slider=null;slides=[];}
function showSlide(index,announce=false){
 if(!slider||!slides.length)return;active=(index+slides.length)%slides.length;
 slides.forEach((el,i)=>{const on=i===active;el.dataset.active=String(on);el.toggleAttribute('inert',!on);if(on)el.removeAttribute('aria-hidden');else el.setAttribute('aria-hidden','true');});
 const counter=slider.querySelector('[data-ar-position]');if(counter)counter.textContent=(active+1)+' / '+slides.length;
 if(announce){const status=slider.querySelector('[data-ar-slider-status]');if(status)status.textContent='Товар '+(active+1)+' из '+slides.length;}
}
function syncToggle(){const button=slider?.querySelector('[data-ar-toggle]');if(button){button.textContent=playing?'Ⅱ':'▶';button.setAttribute('aria-label',playing?'Приостановить смену товаров':'Возобновить смену товаров');button.title=playing?'Пауза':'Продолжить';}}
function startTimer(){if(timer!==null)window.clearInterval(timer);timer=null;if(!playing||slides.length<2)return;timer=window.setInterval(()=>{if(!slider||!slider.isConnected){unmount();return;}if(document.hidden||slider.contains(document.activeElement)||(window.matchMedia('(hover: hover)').matches&&slider.matches(':hover')))return;const rect=slider.getBoundingClientRect();if(rect.bottom<=0||rect.top>=window.innerHeight)return;showSlide(active+1);},4000);}
function mount(){unmount();mountEngagement();slider=app.querySelector('[data-ar-slider]');if(!slider)return;slides=Array.from(slider.querySelectorAll('[data-ar-slide]'));active=0;playing=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;const controls=slider.querySelector('[data-ar-controls]');if(controls)controls.hidden=false;showSlide(0);syncToggle();startTimer();}
app.addEventListener('click',e=>{const button=e.target.closest?.('[data-ar-step],[data-ar-toggle]');if(!button||!slider||!slider.contains(button))return;if(button.hasAttribute('data-ar-toggle')){playing=!playing;syncToggle();}else showSlide(active+Number(button.dataset.arStep),true);startTimer();});
return Object.freeze({render,mount,unmount});}
window.HlebArticles=Object.freeze({posts,meta,get,title,create,recommend,capacity});
})();
